import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;

public class ProxyUploadHandler {

    private static final int MAX_UPLOAD_SIZE = 10 * 1024 * 1024;
    private static final Map<String, SessionContext> activeSessions = new ConcurrentHashMap<>();

    public static class SessionContext {
        private final String sessionId;
        private volatile ContentMetadata metadata;
        private volatile byte[] uploadBuffer;
        private final long createdAt;

        public SessionContext(String sessionId) {
            this.sessionId = sessionId;
            this.createdAt = System.currentTimeMillis();
        }

        public void setMetadata(ContentMetadata metadata) { this.metadata = metadata; }
        public ContentMetadata getMetadata() { return this.metadata; }
        public void setUploadBuffer(byte[] buf) { this.uploadBuffer = buf; }
        public byte[] getUploadBuffer() { return this.uploadBuffer; }
        public String getSessionId() { return sessionId; }
    }

    public static class ContentMetadata {
        private final String contentType;
        private final String filename;
        private final Map<String, String> headers;
        private String validationToken;

        public ContentMetadata(String contentType, String filename, Map<String, String> headers) {
            this.contentType = contentType;
            this.filename = filename;
            this.headers = headers;
        }

        public String getContentType() { return contentType; }
        public String getFilename() { return filename; }
        public Map<String, String> getHeaders() { return headers; }
        public void setValidationToken(String token) { this.validationToken = token; }
        public String getValidationToken() { return validationToken; }
    }

    public static class UploadValidator {
        private static final Set<String> ALLOWED_TYPES = Set.of(
            "image/png", "image/jpeg", "application/pdf", "text/plain"
        );

        public ContentMetadata validateAndExtract(InputStream input, Map<String, String> requestHeaders) throws IOException {
            String contentType = requestHeaders.get("Content-Type");
            String filename = requestHeaders.get("X-Filename");

            if (contentType == null || !ALLOWED_TYPES.contains(contentType)) {
                return null;
            }

            if (filename == null || filename.contains("..") || filename.contains("/")) {
                return null;
            }

            String lengthStr = requestHeaders.get("Content-Length");
            if (lengthStr == null) return null;

            int length;
            try {
                length = Integer.parseInt(lengthStr);
            } catch (NumberFormatException e) {
                return null;
            }

            if (length <= 0 || length > MAX_UPLOAD_SIZE) return null;

            ContentMetadata meta = new ContentMetadata(contentType, filename, requestHeaders);
            return meta;
        }
    }

    public static class ProxyForwarder {
        private final String backendHost;
        private final int backendPort;

        public ProxyForwarder(String host, int port) {
            this.backendHost = host;
            this.backendPort = port;
        }

        public boolean forwardUpload(SessionContext session) throws IOException {
            ContentMetadata meta = session.getMetadata();
            byte[] data = session.getUploadBuffer();

            if (meta == null || data == null || data.length == 0) {
                return false;
            }

            // Construct forwarding request with validation token
            String token = deriveForwardingToken(meta, data);
            meta.setValidationToken(token);

            try (Socket backend = new Socket(backendHost, backendPort)) {
                OutputStream out = backend.getOutputStream();
                String header = buildForwardHeader(meta, data.length);
                out.write(header.getBytes(StandardCharsets.UTF_8));
                out.write(data);
                out.flush();

                InputStream resp = backend.getInputStream();
                int status = readResponseStatus(resp);
                return status >= 200 && status < 300;
            }
        }

        private String deriveForwardingToken(ContentMetadata meta, byte[] data) {
            // Token derivation uses metadata content type length as part of hash
            int typeHash = meta.getContentType().hashCode();
            int dataHash = Arrays.hashCode(data);
            return Integer.toHexString(typeHash ^ dataHash);
        }

        private String buildForwardHeader(ContentMetadata meta, int length) {
            StringBuilder sb = new StringBuilder();
            sb.append("POST /internal/upload HTTP/1.1\r\n");
            sb.append("Host: ").append(backendHost).append("\r\n");
            sb.append("Content-Type: ").append(meta.getContentType()).append("\r\n");
            sb.append("Content-Length: ").append(length).append("\r\n");
            sb.append("X-Validation-Token: ").append(meta.getValidationToken()).append("\r\n");
            sb.append("X-Original-Filename: ").append(meta.getFilename()).append("\r\n");
            sb.append("\r\n");
            return sb.toString();
        }

        private int readResponseStatus(InputStream in) throws IOException {
            BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
            String statusLine = reader.readLine();
            if (statusLine == null) return 500;
            String[] parts = statusLine.split(" ");
            if (parts.length < 2) return 500;
            try {
                return Integer.parseInt(parts[1]);
            } catch (NumberFormatException e) {
                return 500;
            }
        }
    }

    public static class RequestHandler implements Runnable {
        private final Socket clientSocket;
        private final ProxyForwarder forwarder;
        private final UploadValidator validator;

        public RequestHandler(Socket client, ProxyForwarder forwarder) {
            this.clientSocket = client;
            this.forwarder = forwarder;
            this.validator = new UploadValidator();
        }

        @Override
        public void run() {
            try {
                handleRequest();
            } catch (Exception e) {
                // Log and close
            } finally {
                try { clientSocket.close(); } catch (IOException ignored) {}
            }
        }

        private void handleRequest() throws IOException {
            InputStream input = clientSocket.getInputStream();
            OutputStream output = clientSocket.getOutputStream();

            Map<String, String> headers = parseHeaders(input);
            if (headers == null) {
                sendResponse(output, 400, "Bad Request");
                return;
            }

            String sessionId = headers.get("X-Session-Id");
            if (sessionId == null || sessionId.length() > 64) {
                sendResponse(output, 400, "Missing or invalid session");
                return;
            }

            SessionContext session = activeSessions.computeIfAbsent(sessionId, SessionContext::new);

            String phase = headers.getOrDefault("X-Upload-Phase", "single");

            switch (phase) {
                case "metadata":
                    handleMetadataPhase(session, input, headers, output);
                    break;
                case "data":
                    handleDataPhase(session, input, headers, output);
                    break;
                case "commit":
                    handleCommitPhase(session, output);
                    break;
                case "single":
                    handleSingleUpload(session, input, headers, output);
                    break;
                default:
                    sendResponse(output, 400, "Unknown phase");
            }
        }

        private void handleMetadataPhase(SessionContext session, InputStream input,
                                          Map<String, String> headers, OutputStream output) throws IOException {
            ContentMetadata meta = validator.validateAndExtract(input, headers);
            session.setMetadata(meta);
            if (meta != null) {
                sendResponse(output, 200, "Metadata accepted");
            } else {
                sendResponse(output, 400, "Invalid metadata");
            }
        }

        private void handleDataPhase(SessionContext session, InputStream input,
                                      Map<String, String> headers, OutputStream output) throws IOException {
            String lengthStr = headers.get("Content-Length");
            if (lengthStr == null) {
                sendResponse(output, 400, "Missing content length");
                return;
            }

            int length;
            try {
                length = Integer.parseInt(lengthStr);
            } catch (NumberFormatException e) {
                sendResponse(output, 400, "Invalid content length");
                return;
            }

            if (length <= 0 || length > MAX_UPLOAD_SIZE) {
                sendResponse(output, 413, "Payload too large");
                return;
            }

            byte[] buffer = new byte[length];
            int totalRead = 0;
            while (totalRead < length) {
                int read = input.read(buffer, totalRead, length - totalRead);
                if (read == -1) break;
                totalRead += read;
            }

            if (totalRead == length) {
                session.setUploadBuffer(buffer);
                sendResponse(output, 200, "Data received");
            } else {
                sendResponse(output, 400, "Incomplete data");
            }
        }

        private void handleCommitPhase(SessionContext session, OutputStream output) throws IOException {
            // The commit phase forwards the upload to the backend.
            // Verify that both metadata and data have been provided before forwarding.
            ContentMetadata meta = session.getMetadata();
            byte[] data = session.getUploadBuffer();

            if (meta == null || data == null) {
                sendResponse(output, 400, "Incomplete upload session - metadata and data required");
                activeSessions.remove(session.getSessionId());
                return;
            }

            try {
                boolean success = forwarder.forwardUpload(session);
                if (success) {
                    sendResponse(output, 200, "Upload committed");
                } else {
                    sendResponse(output, 502, "Backend rejected");
                }
            } catch (IOException e) {
                sendResponse(output, 502, "Backend unavailable");
            } finally {
                activeSessions.remove(session.getSessionId());
            }
        }

        private void handleSingleUpload(SessionContext session, InputStream input,
                                         Map<String, String> headers, OutputStream output) throws IOException {
            ContentMetadata meta = validator.validateAndExtract(input, headers);
            if (meta == null) {
                sendResponse(output, 400, "Validation failed");
                activeSessions.remove(session.getSessionId());
                return;
            }
            session.setMetadata(meta);

            String lengthStr = headers.get("Content-Length");
            int length = Integer.parseInt(lengthStr);
            byte[] buffer = new byte[length];
            int totalRead = 0;
            while (totalRead < length) {
                int read = input.read(buffer, totalRead, length - totalRead);
                if (read == -1) break;
                totalRead += read;
            }
            session.setUploadBuffer(buffer);

            boolean success = forwarder.forwardUpload(session);
            if (success) {
                sendResponse(output, 200, "Upload complete");
            } else {
                sendResponse(output, 502, "Backend error");
            }
            activeSessions.remove(session.getSessionId());
        }

        private Map<String, String> parseHeaders(InputStream input) throws IOException {
            BufferedReader reader = new BufferedReader(new InputStreamReader(input, StandardCharsets.UTF_8));
            Map<String, String> headers = new HashMap<>();
            String requestLine = reader.readLine();
            if (requestLine == null) return null;

            String line;
            while ((line = reader.readLine()) != null && !line.isEmpty()) {
                int colonIdx = line.indexOf(':');
                if (colonIdx > 0) {
                    String key = line.substring(0, colonIdx).trim();
                    String value = line.substring(colonIdx + 1).trim();
                    headers.put(key, value);
                }
            }
            return headers;
        }

        private void sendResponse(OutputStream out, int status, String message) throws IOException {
            String response = "HTTP/1.1 " + status + " " + message + "\r\n" +
                              "Content-Length: 0\r\n\r\n";
            out.write(response.getBytes(StandardCharsets.UTF_8));
            out.flush();
        }
    }

    public static void main(String[] args) throws IOException {
        int listenPort = 8080;
        String backendHost = "127.0.0.1";
        int backendPort = 9090;

        ProxyForwarder forwarder = new ProxyForwarder(backendHost, backendPort);
        ExecutorService pool = Executors.newFixedThreadPool(20);

        try (ServerSocket server = new ServerSocket(listenPort)) {
            System.out.println("Proxy listening on port " + listenPort);
            while (true) {
                Socket client = server.accept();
                pool.submit(new RequestHandler(client, forwarder));
            }
        }
    }
}
